// Extract sender + subject + body from Gmail trigger payload
const msg = $input.first().json;

// Try common shape variants
const headers = msg.payload?.headers || [];
const getHeader = (name) => (headers.find(h => h.name.toLowerCase() === name.toLowerCase())?.value) || '';

const fromRaw = msg.From || getHeader('From') || '';
const subject = msg.Subject || getHeader('Subject') || '(no subject)';
const body    = (msg.snippet || msg.text || msg.textPlain || '').substring(0, 2000);

// Extract just the email address from 'Name <email@x.com>'
const emailMatch = fromRaw.match(/<([^>]+)>/) || fromRaw.match(/([\w.-]+@[\w.-]+\.\w+)/);
const senderEmail = (emailMatch ? emailMatch[1] : fromRaw).toLowerCase().trim();

// Skip our own outbound / automation loops
const SKIP_DOMAINS = ['mailer-daemon', 'noreply', 'no-reply', 'notifications@'];
if (SKIP_DOMAINS.some(d => senderEmail.includes(d))) {
  return [];
}

return [{ json: { senderEmail, subject, body, receivedAt: new Date().toISOString(), messageId: msg.id } }];

// Parse AI response and merge with parsed reply + client data.
const reply = $('Parse Reply').first().json;
const clientRow = $('Match Client').first()?.json || null;
const aiRaw = $input.first().json;

let ai = null;
try {
  const text = aiRaw?.content?.[0]?.text || '';
  ai = JSON.parse(text);
} catch (e) { ai = null; }

const validClasses = ['HOT','WARM','OBJECTION','NOT_NOW','REFERRAL','UNSUBSCRIBE','BAD_FIT','COMPLAINT','AUTO_REPLY'];
if (!ai || !validClasses.includes(ai.class)) {
  ai = {
    class: 'WARM',
    confidence: 'low',
    oneLineSummary: 'AI unavailable — defaulted to WARM, owner should review manually',
    suggestedResponse: 'Read the reply and respond within the day.',
    urgencyMinutes: 240
  };
}

return [{
  json: {
    ...reply,
    clientName:    clientRow?.['Client Name'] || 'Unknown (not in Sheet)',
    clientKnown:   !!clientRow,
    prevStatus:    clientRow?.['Status'] || 'Unknown',
    prevOptedOut:  clientRow?.['Opted Out'] || 'No',
    replyClass:    ai.class,
    confidence:    ai.confidence,
    summary:       ai.oneLineSummary,
    suggestedResponse: ai.suggestedResponse,
    urgencyMinutes: ai.urgencyMinutes,
    isUnsubscribe: ai.class === 'UNSUBSCRIBE',
    isComplaint:   ai.class === 'COMPLAINT',
    isHot:         ai.class === 'HOT',
    needsOwner:    ['HOT','OBJECTION','COMPLAINT','UNSUBSCRIBE'].includes(ai.class),
    skipRest:      ai.class === 'AUTO_REPLY'
  }
}];
